import 'package:vaultvoice/features/models/domain/catalog_verifier.dart';

/// Pinned Ed25519 public keys for the model catalog (MDL-01).
///
/// At most two: the current key and, during a rotation, its successor (or
/// predecessor). Rotation: add the new key here and ship that app version,
/// then switch signing to the new key, then drop the old key in a later
/// release. Private keys never live in this repository
/// (tools/model-catalog/README.md).
///
/// PRODUCT-DECISION: `vv-catalog-dev-2026a` is a development key generated by
/// the MDL-01 agent; its private half is not kept in the repo. Before release
/// the owner generates the production key offline (`catalog.py keygen`),
/// replaces this entry and re-signs the bundled catalog (follow-up MDL-05).
const kPinnedCatalogKeysBase64 = <String, String>{
  // key_id c6ced0f07343ec41
  'vv-catalog-dev-2026a': 'l5vmi7GbOkg3ut65n8IlF/W2N2+eGgTkGb1R8bDdTKk=',
};

/// [kPinnedCatalogKeysBase64] as verifier keys.
List<CatalogPublicKey> pinnedCatalogKeys() => [
  for (final b64 in kPinnedCatalogKeysBase64.values)
    CatalogPublicKey.base64(b64),
];
